#!/usr/bin/env bash
# Generated by kubegen from examples/vks.yaml - re-generate instead of editing.
# Creates the vks cluster "team-a".
set -euo pipefail

die() { echo "error: $*" >&2; exit 1; }

# Required tools
missing=0
need() {
  command -v "$1" >/dev/null 2>&1 && return
  echo "error: required tool '$1' is not installed or not in PATH" >&2
  echo "       install it from: $2" >&2
  missing=1
}
need kubectl https://kubernetes.io/docs/tasks/tools/
need kubectl-vsphere 'https://supervisor.example.com/ (Kubernetes CLI Tools page served by your Supervisor)'
[ "$missing" -eq 0 ] || exit 127

KUBECONFIG_OUT=./team-a.kubeconfig

echo '==> Logging in to Supervisor supervisor.example.com'
# Set KUBECTL_VSPHERE_PASSWORD to avoid the password prompt.
kubectl vsphere login --server supervisor.example.com --vsphere-username devops@vsphere.local
kubectl config use-context team-a-ns

echo '==> Checking access to vSphere Namespace team-a-ns'
kubectl get clusters -n team-a-ns >/dev/null 2>&1 || die 'cannot list clusters in vSphere Namespace team-a-ns; log in to the Supervisor first'

echo '==> Creating VKS cluster team-a'
CONFIG_FILE="$(mktemp)"
trap 'rm -f "$CONFIG_FILE"' EXIT
cat > "$CONFIG_FILE" <<'KUBEGEN_EOF'
apiVersion: cluster.x-k8s.io/v1beta1
kind: Cluster
metadata:
  name: "team-a"
  namespace: "team-a-ns"
  labels:
    "team": "a"
spec:
  clusterNetwork:
    pods:
      cidrBlocks: ["192.168.156.0/20"]
    services:
      cidrBlocks: ["10.96.0.0/12"]
  topology:
    class: "builtin-generic-v3.4.0"
    classNamespace: "vmware-system-vks-public"
    version: "v1.33.1+vmware.1-fips"
    controlPlane:
      replicas: 3
    variables:
      - name: vmClass
        value: "best-effort-medium"
      - name: storageClass
        value: "vsan-default-storage-policy"
    workers:
      machineDeployments:
        - class: node-pool
          name: "workers"
          replicas: 3
        - class: node-pool
          name: "large"
          metadata:
            annotations:
              cluster.x-k8s.io/cluster-api-autoscaler-node-group-min-size: "1"
              cluster.x-k8s.io/cluster-api-autoscaler-node-group-max-size: "5"
          variables:
            overrides:
              - name: vmClass
                value: "guaranteed-xlarge"
KUBEGEN_EOF
kubectl apply -f "$CONFIG_FILE"

echo '==> Waiting for the cluster to become ready (up to 45m)'
kubectl wait --for=condition=Ready cluster/team-a -n team-a-ns --timeout=45m

echo '==> Fetching credentials'
(umask 077; kubectl get secret team-a-kubeconfig -n team-a-ns -o 'jsonpath={.data.value}' | base64 -d > "$KUBECONFIG_OUT")

echo '==> Verifying access to team-a'
kubectl --kubeconfig "$KUBECONFIG_OUT" get nodes -o wide

echo "Cluster team-a is ready. Kubeconfig: $KUBECONFIG_OUT"
